#!/usr/bin/env node
/**
 * copy-playground.mjs — stage the playground into website/static/playground/
 *
 * Docusaurus copies website/static/ verbatim to the build root, so the
 * playground is deployed UNVERSIONED at /jekyll-js/playground/ — never
 * committed into static/ (gitignored, regenerated by CI on every build).
 *
 * Usage: node scripts/copy-playground.mjs
 * Runs automatically as `npm run prebuild` before `docusaurus build`.
 *
 * Note: root dist/ is a gitignored build artifact, so this script builds
 * it from src/ via `npm run build` when the bundles are missing (esbuild,
 * a few seconds). CI therefore needs root devDependencies installed.
 */
import { cp, mkdir, readdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';

const root = join(dirname(fileURLToPath(import.meta.url)), '..'); // website/
const repoRoot = join(root, '..'); // jekyll-js/
const playgroundSrc = join(repoRoot, 'playground');
const distSrc = join(repoRoot, 'dist');
const playgroundDest = join(root, 'static', 'playground');
const distDest = join(playgroundDest, 'dist');

// dist/ is a gitignored build artifact — make sure the bundles exist,
// building them from src/ if needed (esbuild, seconds).
let bundles = [];
try {
  bundles = (await readdir(distSrc)).filter((f) => f.endsWith('.js'));
} catch { /* missing -> build below */ }
if (bundles.length === 0) {
  console.log('[copy-playground] root dist/ bundles missing — running `npm run build` at repo root…');
  execFileSync('npm', ['run', 'build'], { cwd: repoRoot, stdio: 'inherit' });
  bundles = (await readdir(distSrc)).filter((f) => f.endsWith('.js'));
}
if (bundles.length === 0) {
  console.error(`[copy-playground] ERROR: still no .js bundles in ${distSrc} after build.`);
  process.exit(1);
}

await mkdir(distDest, { recursive: true });

// 1. Copy playground files (index.html, assets) — but NOT playground/dist/
//    (that dir is an empty placeholder in the repo; engine bundles come from step 2).
await cp(playgroundSrc, playgroundDest, {
  recursive: true,
  filter: (src) => src === playgroundSrc || !src.startsWith(join(playgroundSrc, 'dist')),
});

// 2. Copy engine bundles root dist/*.js → static/playground/dist/
//    (index.html loads them via ./dist/<bundle>.js, so the relative path is
//    preserved exactly as the playground expects).
for (const bundle of bundles) {
  await cp(join(distSrc, bundle), join(distDest, bundle));
}

console.log(
  `[copy-playground] staged ${bundles.length} engine bundles ` +
  `(${bundles.join(', ')}) into static/playground/`
);
